 /** Stable, session-independent match identifier for URL routing.
  *
- * Slug = `${cargoId}--${vesselId}`. The double-dash separator is safe
- * because email IDs in demo data use single dashes only (e.g. "demo-cargo-001").
- * Production email IDs are UUIDs or similar — never contain `--`.
+ * Slug = `${cargoId}@${cargoItemIndex}--${vesselId}@${vesselItemIndex}`.
+ * The double-dash separator is safe because email IDs in demo data use single
+ * dashes only (e.g. "demo-cargo-001"). Production email IDs are UUIDs or similar
+ * — never contain `--`. The `@` separator encodes item indices; it is safe in
+ * Next.js route segments and never appears in email ID strings.
+ *
+ * Backward-compatible parse: slugs without `@` (old format) parse with item
+ * indices defaulting to 0 — existing dashboard links continue to work.
  */

-export function toMatchSlug(cargoId: string, vesselId: string): string {
-  return `${cargoId}--${vesselId}`;
+export function toMatchSlug(
+  cargoId: string,
+  vesselId: string,
+  cargoItemIndex = 0,
+  vesselItemIndex = 0,
+): string {
+  return `${cargoId}@${cargoItemIndex}--${vesselId}@${vesselItemIndex}`;
 }

-export function fromMatchSlug(
-  slug: string,
-): { cargo_id: string; vessel_id: string } | null {
-  const idx = slug.indexOf('--');
-  if (idx < 1) return null; // no separator or empty cargo_id
-  const cargo_id = slug.slice(0, idx);
-  const vessel_id = slug.slice(idx + 2);
-  if (!vessel_id) return null;
-  return { cargo_id, vessel_id };
+export function fromMatchSlug(slug: string): {
+  cargo_id: string;
+  vessel_id: string;
+  cargo_item_index: number;
+  vessel_item_index: number;
+} | null {
+  const dIdx = slug.indexOf('--');
+  if (dIdx < 1) return null;
+  const cargoPart = slug.slice(0, dIdx);
+  const vesselPart = slug.slice(dIdx + 2);
+  if (!vesselPart) return null;
+
+  const cAt = cargoPart.lastIndexOf('@');
+  const vAt = vesselPart.lastIndexOf('@');
+
+  const cargo_id = cAt >= 0 ? cargoPart.slice(0, cAt) : cargoPart;
+  const cargo_item_index = cAt >= 0 ? (parseInt(cargoPart.slice(cAt + 1), 10) || 0) : 0;
+  const vessel_id = vAt >= 0 ? vesselPart.slice(0, vAt) : vesselPart;
+  const vessel_item_index = vAt >= 0 ? (parseInt(vesselPart.slice(vAt + 1), 10) || 0) : 0;
+
+  if (!cargo_id || !vessel_id) return null;
+  return { cargo_id, vessel_id, cargo_item_index, vessel_item_index };
 }
