+++ b/lib/migrations/051-matches-item-pair-unique.ts
@@ -0,0 +1,52 @@
+import type { Migration } from './types';
+
+/**
+ * Change the matches unique constraint from per-email-pair to per-item-pair.
+ *
+ * Before: UNIQUE(cargo_id, vessel_id, COALESCE(user_id, ''))
+ *   → only one row per (cargo email, vessel email), silently dropping the second
+ *     cargo item of a letter when two items share the same cargo email ID.
+ *
+ * After:  UNIQUE(cargo_id, vessel_id, COALESCE(user_id, ''), cargo_item_index, vessel_item_index)
+ *   → one row per (cargo email, cargo item, vessel email, vessel item), so all
+ *     cargo items in a multi-item letter produce independent match rows.
+ *
+ * The old index is dropped first; dedup keeps the highest-score survivor per
+ * new key before the new index is created.
+ */
+const migration051: Migration = {
+  version: 51,
+  name: '051-matches-item-pair-unique',
+  up(db) {
+    // 1. Drop the old per-email-pair unique index.
+    db.exec(`DROP INDEX IF EXISTS idx_matches_unique_cargo_vessel_user`);
+
+    // 2. Remove duplicate rows under the new key, keeping the highest-score one.
+    db.exec(`
+      DELETE FROM matches
+      WHERE rowid NOT IN (
+        SELECT MAX(rowid) FROM matches
+        GROUP BY cargo_id, vessel_id, COALESCE(user_id, ''),
+                 COALESCE(cargo_item_index, 0), COALESCE(vessel_item_index, 0)
+      )
+    `);
+
+    // 3. Create the new per-item-pair unique index.
+    db.exec(`
+      CREATE UNIQUE INDEX IF NOT EXISTS idx_matches_unique_item_pair
